/**
 * Named aliases onto the OpenAPI-generated schema (`./generated/schema.d.ts`,
 * regenerated by `npm run generate:api-types` — see that file's own header
 * and this repo's README). Every request/response shape used anywhere in
 * `src/api/*.ts` or `src/features/**` comes from here, never redeclared by
 * hand — see docs/frontend/state-management.md#type-strategy.
 *
 * Owner: frontend-api-agent. This file only aliases; it must never widen,
 * narrow, or reshape a generated type.
 */

import type { components } from './generated/schema'

type Schemas = components['schemas']

// User Service
export type CreateUserRequest = Schemas['CreateUserRequest']
export type UserResponse = Schemas['UserResponse']
export type UserPreferencesResponse = Schemas['UserPreferencesResponse']
