// Job Discovery Service
export type CreateJobSourceRequest = Schemas['CreateJobSourceRequest']
export type JobSourceResponse = Schemas['JobSourceResponse']

// Job Matching Service
export type JobMatchResponse = Schemas['JobMatchResponse']
export type ProfileMatchScore = Schemas['ProfileMatchScore']

// Contact Discovery Service
export type ContactResponse = Schemas['ContactResponse']
