// nothing in this app may define a competing status value.
export type ApplicationStatus = Schemas['ApplicationStatus']
export type OutreachStatus = Schemas['OutreachStatus']
export type ResumeStatus = Schemas['ResumeStatus']
export type ContactStatus = Schemas['ContactStatus']
export type ContactType = Schemas['ContactType']
export type JobProcessingStatus = Schemas['JobProcessingStatus']
